import moment from 'moment-timezone'
import dayjs from '../src'
import utc from '../src/plugin/utc'
import timezone from '../src/plugin/timezone'

dayjs.extend(utc)
dayjs.extend(timezone)

afterEach(() => {
  MockDate.reset()
})

const NY = 'America/New_York'

describe('d.tz with absolute instants', () => {
  it('number timestamp', () => {
    const d = dayjs.tz(1401638400000, NY)
    console.log('NUM_FORMAT=' + d.format())
    console.log('NUM_VALUEOF=' + d.valueOf())
    expect(d.format()).toBe('2014-06-01T12:00:00-04:00')
    expect(d.valueOf()).toBe(1401638400000)
    expect(d.format()).toBe(moment(1401638400000).tz(NY).format())
    expect(d.valueOf()).toBe(moment(1401638400000).tz(NY).valueOf())
  })

  it('JS Date', () => {
    const d = dayjs.tz(new Date(1401638400000), NY)
    console.log('DATE_FORMAT=' + d.format())
    console.log('DATE_VALUEOF=' + d.valueOf())
    expect(d.format()).toBe('2014-06-01T12:00:00-04:00')
    expect(d.valueOf()).toBe(1401638400000)
  })

  it('dayjs object', () => {
    const d = dayjs.tz(dayjs(1401638400000), NY)
    console.log('DAYJS_FORMAT=' + d.format())
    console.log('DAYJS_VALUEOF=' + d.valueOf())
    expect(d.format()).toBe('2014-06-01T12:00:00-04:00')
    expect(d.valueOf()).toBe(1401638400000)
  })

  it('moment object', () => {
    const d = dayjs.tz(moment(1401638400000), NY)
    console.log('MOMENT_FORMAT=' + d.format())
    console.log('MOMENT_VALUEOF=' + d.valueOf())
    expect(d.format()).toBe('2014-06-01T12:00:00-04:00')
    expect(d.valueOf()).toBe(1401638400000)
  })
})

describe('string path unchanged', () => {
  it('wall clock string', () => {
    const d = dayjs.tz('2014-06-01 12:00', NY)
    console.log('STR_FORMAT=' + d.format())
    expect(d.format()).toBe('2014-06-01T12:00:00-04:00')
  })

  it('convert between timezones', () => {
    const d = dayjs.tz('2014-06-01 12:00', NY).tz('America/Los_Angeles')
    console.log('STR_CONVERT_FORMAT=' + d.format())
    expect(d.format()).toBe('2014-06-01T09:00:00-07:00')
  })

  it('ISO string with Z', () => {
    const d = dayjs.tz('2014-06-01T12:00:00Z', NY)
    console.log('ISOZ_FORMAT=' + d.format())
    expect(d.format()).toBe('2014-06-01T08:00:00-04:00')
    expect(d.format()).toBe(moment.tz('2014-06-01T12:00:00Z', NY).format())
  })
})

describe('proto.tz milliseconds / offset formatting', () => {
  it('fixed ms timestamp', () => {
    MockDate.set(new Date(1401638400123))
    const d = dayjs().tz(NY)
    console.log('MS_Z=' + d.format('Z'))
    console.log('MS_ZZ=' + d.format('ZZ'))
    console.log('MS_FORMAT=' + d.format())
    console.log('MS_VALUEOF=' + d.valueOf())
    console.log('MS_SSS=' + d.format('SSS'))
    expect(d.format('Z')).toBe('-04:00')
    expect(d.format('ZZ')).toBe('-0400')
    expect(d.format()).toBe('2014-06-01T12:00:00-04:00')
    expect(d.valueOf()).toBe(1401638400123)
    expect(d.format('SSS')).toBe('123')
  })

  it('arbitrary ms now', () => {
    MockDate.set(new Date())
    const d = dayjs().tz(NY)
    const m = moment().tz(NY)
