    console.log('MOMENT_FORMAT=' + m.format())
    expect(d.format('Z')).toMatch(/^[+-]\d\d:\d\d$/)
    expect(d.format('Z')).toBe(m.format('Z'))
    expect(d.format()).toBe(m.format())
