import moment from 'moment'
import dayjs from '../src'
import weekOfYear from '../src/plugin/weekOfYear'
import weekYear from '../src/plugin/weekYear'
import '../src/locale/en-gb'
dayjs.extend(weekOfYear)
dayjs.extend(weekYear)
dayjs.prototype.weekYear = function () {
  const month = this.month()
  const weekOfYear = this.week()
  const year = this.year()
  if (weekOfYear === 1 && month === 11) return year + 1
  if (month === 0 && weekOfYear >= 52) return year - 1
  return year
}
dayjs.locale({ ...dayjs.Ls['en-gb'], name: 'x', weekStart: 1, yearStart: 4 }, null, true)
moment.locale('en-gb')
it('sweep', () => {
  let bad = 0
  let total = 0
  let d = dayjs('2015-01-01')
  const end = dayjs('2023-01-01')
  while (d.isBefore(end)) {
    const s = d.format('YYYY-MM-DD')
    const m = moment(s)
    const dj = d.locale('x')
    total += 1
    if (dj.week() !== m.week() || dj.weekYear() !== m.weekYear()) {
      bad += 1
      if (bad <= 20) console.log(`MISMATCH ${s} dayjs(w=${dj.week()},wy=${dj.weekYear()}) moment(w=${m.week()},wy=${m.weekYear()})`)
    }
    d = d.add(1, 'day')
  }
  console.log(`TOTAL=${total} MISMATCHES=${bad}`)
  expect(bad).toBe(0)
})
EOF
